<script setup lang="ts">
import { router } from '@inertiajs/vue3'; import { ClipboardList, Search } from 'lucide-vue-next'; import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import Button from '@/Core/Components/Button.vue'; import Card from '@/Core/Components/Card.vue'; import DataTable, { type Column } from '@/Core/Components/DataTable.vue'; import EmptyState from '@/Core/Components/EmptyState.vue'; import Input from '@/Core/Components/Input.vue'; import PageHeader from '@/Core/Components/PageHeader.vue'; import Pagination from '@/Core/Components/Pagination.vue'; import Select from '@/Core/Components/Select.vue'; import { useFormat } from '@/Core/composables/useFormat'; import TenantLayout from '@/Core/Layouts/TenantLayout.vue'; import { route } from '@/Core/lib/route'; import type { Paginated } from '@/Core/types'; import CrmStatusBadge from '../../../Components/CrmStatusBadge.vue'; import SalesNav from '../../../Components/SalesNav.vue'; import type { SalesOrderStatus, SalesOrderSummary } from '../../../Components/types';
defineOptions({ layout: TenantLayout }); const props = defineProps<{ orders: Paginated<SalesOrderSummary>; filters: { search: string; status: SalesOrderStatus | null }; statuses: SalesOrderStatus[] }>(); const { t } = useI18n(); const format = useFormat(); const search = ref(props.filters.search); const status = ref(props.filters.status ?? ''); const statusOptions = computed(() => [{ value: '', label: t('crm.common.all') }, ...props.statuses.map((value) => ({ value, label: t(`crm.status.${value}`) }))]); const columns = computed<Column[]>(() => [{ key: 'number', label: t('crm.fields.number') }, { key: 'status', label: t('crm.fields.status') }, { key: 'customer', label: t('crm.sales.quotes.customer') }, { key: 'ordered', label: t('crm.sales.orders.orderedAt') }, { key: 'total', label: t('crm.sales.quotes.total'), align: 'right' }, { key: 'actions', label: t('crm.common.actions'), srOnly: true, align: 'right' }]); function apply(): void { router.get(route('crm.sales.orders.index'), { search: search.value || undefined, status: status.value || undefined }, { preserveState: true, replace: true }); }
</script>
<template><PageHeader :eyebrow="t('crm.eyebrow')" :title="t('crm.sales.orders.title')" :description="t('crm.sales.orders.description')" /><SalesNav current="orders" /><Card flush><DataTable :columns="columns" :rows="orders.data" row-key="id" :caption="t('crm.sales.orders.title')" storage-key="crm-orders"><template #toolbar><form class="flex min-w-0 flex-1 flex-wrap items-end gap-2" @submit.prevent="apply"><Input v-model="search" :label="t('crm.sales.orders.search')" class="min-w-48 flex-1" type="search"><template #leading><Search class="size-4" aria-hidden="true" /></template></Input><Select v-model="status" :options="statusOptions" :label="t('crm.fields.status')" class="w-full sm:w-40" /><Button type="submit" size="sm">{{ t('crm.common.search') }}</Button></form></template><template #cell-number="{ row }"><Button size="sm" variant="ghost" :href="route('crm.sales.orders.show', { salesOrder: row.id })"><span class="font-mono text-xs">{{ row.number }}</span></Button></template><template #cell-status="{ row }"><CrmStatusBadge :status="row.status" /></template><template #cell-customer="{ row }"><span class="text-ink-muted">{{ row.company?.name ?? row.contact?.name ?? t('crm.common.notSet') }}</span></template><template #cell-ordered="{ row }"><span class="tabular text-ink-muted">{{ format.date(row.orderedAt) }}</span></template><template #cell-total="{ row }"><span class="tabular font-mono">{{ format.money(row.totalAmount, row.currency) }}</span></template><template #cell-actions="{ row }"><Button size="sm" variant="ghost" :href="route('crm.sales.orders.show', { salesOrder: row.id })">{{ t('crm.common.view') }}</Button></template><template #empty><EmptyState :title="t('crm.sales.orders.empty')"><template #icon><ClipboardList /></template></EmptyState></template></DataTable><Pagination :meta="orders" /></Card></template>
